MATCH (fa:FlightAccident)-[:departsFrom]->(a:Airport {name: 'Skopje International Airport'}),
      (fa)-[:operatedBy]->(o:Operator)
RETURN DISTINCT o.name AS operator_name;

MATCH (fa:FlightAccident)-[:destinedFor]->(apt:Airport {name: 'Strasbourg Airport'}),
      (fa)-[:operatedBy]->(op:Operator)
RETURN DISTINCT op.name AS operatorName;

MATCH (fa:FlightAccident)-[:departsFrom]->(ap:Airport)
WHERE fa.flight_number = 'SA201' OR fa.name CONTAINS 'South African Airways Flight 201'
RETURN ap.name AS AirportName;

MATCH (f:FlightAccident)-[:operatedBy]->(op:Operator)
WHERE f.flight_number =~ '.*3603.*' OR f.name CONTAINS 'Aeroflot Flight 3603'
RETURN DISTINCT op.name AS operator, op.country AS country;

MATCH (m1:AircraftModel {name: "Douglas A-26 Invader"}),
      (m2:AircraftModel {name: "Junkers Ju 52"})
RETURN abs(toFloat(m1.height_metre) - toFloat(m2.height_metre)) AS height_difference_metre;

MATCH (fa:FlightAccident)-[r:departsFrom|destinedFor]->(a:Airport)
WHERE a.name IN ["Aeroparque Jorge Newbery", "Ingeniero Aeronáutico Ambrosio L.V. Taravella International Airport"]
RETURN DISTINCT fa.name AS accident_name;

MATCH (fa:FlightAccident)
WHERE fa.flight_number = "FlyMontserrat Flight 107" OR fa.name = "FlyMontserrat Flight 107"
RETURN fa.flight_number AS flightNumber, fa.name AS flightName, fa.number_of_survivors AS survivors;

MATCH (model:AircraftModel)-[:manufacturedBy]->(m:AircraftManufacturer)
WHERE m.name = "PZL Mielec" OR any(a IN m.aliases WHERE a = "PZL Mielec")
RETURN DISTINCT model.name AS aircraftModelName;

MATCH (fa:FlightAccident)
WHERE fa.flight_number =~ ".*521.*" AND fa.name CONTAINS "Emirates"
RETURN fa.date AS AccidentDate;

MATCH (f:FlightAccident)-[:destinedFor]->(a:Airport)
WHERE f.name IN ['LOT Polish Airlines Flight 16', 'SAS Flight 751']
RETURN DISTINCT a.name AS destination_airport;

MATCH (fa:FlightAccident)-[:departsFrom]->(a:Airport)<-[:destinedFor]-(fa)
WHERE date(fa.date) > date('1943-08-01')
RETURN DISTINCT fa.name AS accidentName;

MATCH (f:FlightAccident)-[:involves]->(a:AircraftModel), (f)-[:operatedBy]->(o:Operator) 
WHERE a.name = "Bombardier CRJ100/200" AND o.name = "Endeavor Air" 
RETURN f.name AS accident_name, f.flight_number AS flight_number;
